// Monta a página de alertas: registro das últimas falhas, a mais recente primeiro.
// Vem do Error Trigger (nome do workflow, nó onde parou, mensagem de erro) ou do gatilho
// manual, que só redesenha a página com o que já está registrado.
const FUSO = $env.GENERIC_TIMEZONE || 'America/Sao_Paulo'; // fuso das datas e horas: vem do .env (GENERIC_TIMEZONE); sem ele, Brasília
// Tema (identidade): vem do .env (TEMA). "aranha" (padrão) ou "neutro". Também decide o prefixo dos nomes de arquivo.
const NEUTRO = $env.TEMA === 'neutro';
const NOME = NEUTRO ? 'Radar de Vagas' : 'Meu Sentido de Aranha';
const PREFIXO = NEUTRO ? '' : 'spider-man-';   // spider-man-ultimas-vagas.html (aranha) ou ultimas-vagas.html (neutro)
const MAX_FALHAS = 50;            // quantas falhas a página lembra
const e = $input.first().json;

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const formata = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: FUSO });

// --- registro: fica na memória do workflow de alerta ---
const store = $getWorkflowStaticData('global');
store.falhas = store.falhas || [];
if (e.execution) { // só o Error Trigger traz "execution"; o gatilho manual não registra nada
  store.falhas.unshift({
    quando: new Date().toISOString(),
    workflow: e.workflow?.name ?? 'workflow desconhecido',
    no: e.execution.lastNodeExecuted ?? 'nó desconhecido',
    erro: e.execution.error?.message ?? 'erro sem mensagem',
  });
  store.falhas = store.falhas.slice(0, MAX_FALHAS);
}
const falhas = store.falhas;

const cartoes = falhas.map((f) => `
    <li class="cartao">
      <p class="quando">${esc(formata(f.quando))}</p>
      <dl>
        <dt>Workflow</dt><dd>${esc(f.workflow)}</dd>
        <dt>Parou no nó</dt><dd>${esc(f.no)}</dd>
        <dt>Erro</dt><dd><pre>${esc(f.erro)}</pre></dd>
      </dl>
    </li>`).join('');

const conteudo = falhas.length
  ? `<ul class="lista">${cartoes}\n  </ul>`
  : '<p class="vazio">Nenhuma falha registrada.</p>';

const html = `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta http-equiv="refresh" content="10">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${NOME} — alertas</title>
<style>
  :root { color-scheme: light dark; --bg: #f6f6f4; --card: #ffffff; --texto: #14161a; --suave: #5b6068; --borda: #dcdcd6; --vermelho: #c8102e; --azul: #1b3a8c; }
  @media (prefers-color-scheme: dark) { :root { --bg: #101114; --card: #1a1c21; --texto: #f2f2f0; --suave: #a3a8b0; --borda: #2c2f36; --vermelho: #ff5a62; --azul: #8fb0ff; } }
  * { box-sizing: border-box; }
  body { margin: 0; background: var(--bg); color: var(--texto); font-family: "Segoe UI", system-ui, -apple-system, sans-serif; line-height: 1.5; }
  main { max-width: 860px; margin: 0 auto; padding: 2rem 1rem 3rem; }
  header { border-bottom: 4px solid var(--vermelho); padding-bottom: 1rem; margin-bottom: 1.5rem; }
  h1 { margin: 0; font-family: "Arial Black", "Segoe UI Black", system-ui, sans-serif; font-size: clamp(1.6rem, 5vw, 2.4rem); text-transform: uppercase; letter-spacing: .02em; line-height: 1.1; }
  .sub { margin: .4rem 0 0; color: var(--suave); }
  .sub a { color: var(--azul); font-weight: 700; }
  .sub a:focus-visible { outline: 3px solid var(--vermelho); outline-offset: 2px; }
  .lista { list-style: none; margin: 0; padding: 0; display: grid; gap: .75rem; }
  .cartao { background: var(--card); border: 1px solid var(--borda); border-left: 6px solid var(--vermelho); border-radius: 8px; padding: 1rem 1.25rem; }
  .quando { margin: 0 0 .5rem; font-weight: 800; }
  dt { color: var(--suave); font-size: .8rem; text-transform: uppercase; letter-spacing: .04em; margin-top: .6rem; }
  dd { margin: .1rem 0 0; font-weight: 600; }
  pre { margin: .1rem 0 0; white-space: pre-wrap; word-break: break-word; font-family: Consolas, "Courier New", monospace; font-size: .95rem; font-weight: 400; }
  .vazio { background: var(--card); border: 1px solid var(--borda); border-radius: 8px; padding: 2rem 1rem; text-align: center; color: var(--suave); }
  footer { margin-top: 1.5rem; color: var(--suave); font-size: .9rem; }
</style>
</head>
<body>
<main>
  <header>
    <h1>Alertas</h1>
    <p class="sub">Registro de falhas &middot; atualizado em ${esc(formata(new Date().toISOString()))} &middot; <a href="${PREFIXO}ultimas-vagas.html">Voltar às vagas</a></p>
  </header>
  ${conteudo}
  <footer>Detalhes de cada execução: abra o n8n e vá em Executions.</footer>
</main>
</body>
</html>`;

return [{ json: { html } }];
